"""800x480 music dashboard: home, metronome, spectrum and numbered notation.

Use the existing, running LCDColorbars and GT911Touch objects. This module never
loads an Overlay, allocates DMA memory, writes PS registers, or produces audio.
All drawing uses an ordinary BGR ndarray followed by one full framebuffer copy.
"""
import base64
from collections import deque
from functools import lru_cache
import json
import math
import time
import zlib

import numpy as np

WIDTH, HEIGHT = 800, 480
MIN_BPM, MAX_BPM = 30, 240
METERS = (2, 3, 4, 6)

# Generated Chinese/Latin alpha masks. No font files or Pillow needed on board.
_FONT_PACK = ''


def _colour(value):
    return tuple(int(value[i:i + 2], 16) for i in (5, 3, 1))


C = {name: _colour(value) for name, value in {
    'background': '#0C1420', 'white': '#1C2737', 'ink': '#EDF3FC',
    'muted': '#96A6BC', 'line': '#2C394D', 'soft': '#243146',
    'accent': '#F0A084', 'accent_dark': '#DA886F', 'accent_light': '#3C2B2C',
    'blue': '#80ABFF', 'blue_light': '#1B304D',
    'green': '#7CD4B0', 'green_light': '#153B36', 'selected': '#E7EFFB',
}.items()}


@lru_cache(maxsize=1)
def _assets():
    data = json.loads(zlib.decompress(base64.b64decode(_FONT_PACK)).decode('utf-8'))
    return {name: (np.frombuffer(base64.b64decode(item['alpha']), dtype=np.uint8)
                   .reshape(item['height'], item['width']).astype(np.uint16),
                   item['width'], item['height']) for name, item in data.items()}


@lru_cache(maxsize=64)
def _rounded_mask(width, height, radius):
    radius = max(0, min(radius, width // 2, height // 2))
    y, x = np.ogrid[:height, :width]
    dx = np.maximum(np.maximum(radius - 0.5 - x, x - (width - radius - 0.5)), 0)
    dy = np.maximum(np.maximum(radius - 0.5 - y, y - (height - radius - 0.5)), 0)
    return dx * dx + dy * dy <= radius * radius


class Canvas:
    """Ordinary RAM image, in the LCD driver's B/G/R byte order."""
    def __init__(self):
        self.image = np.empty((HEIGHT, WIDTH, 3), dtype=np.uint8)

    def rect(self, bounds, colour):
        x0, y0, x1, y1 = bounds
        self.image[y0:y1, x0:x1] = colour

    def rounded(self, bounds, radius, colour, border=None):
        x0, y0, x1, y1 = bounds
        roi = self.image[y0:y1, x0:x1]
        roi[_rounded_mask(x1 - x0, y1 - y0, radius)] = border or colour
        if border is not None:
            self.rounded((x0 + 1, y0 + 1, x1 - 1, y1 - 1), max(0, radius - 1), colour)

    def circle(self, cx, cy, radius, colour, border=None):
        self.rounded((cx - radius, cy - radius, cx + radius + 1, cy + radius + 1),
                     radius, colour, border)

    def text(self, name, x, y, colour, centered=False):
        alpha, width, height = _assets()[name]
        if centered:
            x, y = int(x - width / 2), int(y - height / 2)
        x, y = int(x), int(y)
        x0, y0, x1, y1 = max(0, x), max(0, y), min(WIDTH, x + width), min(HEIGHT, y + height)
        if x1 <= x0 or y1 <= y0:
            return
        a = alpha[y0 - y:y1 - y, x0 - x:x1 - x, None]
        roi = self.image[y0:y1, x0:x1]
        roi[:] = ((roi.astype(np.uint16) * (255 - a) +
                   np.asarray(colour, dtype=np.uint16) * a + 127) // 255).astype(np.uint8)

    def number(self, value, cx, baseline, colour):
        digits = str(value)
        left = int(cx - len(digits) * 58 / 2)
        for index, digit in enumerate(digits):
            name = 'digit_' + digit
            _, width, height = _assets()[name]
            self.text(name, left + index * 58 + (58 - width) // 2,
                      baseline - height, colour)


class MetronomeState:
    """Visual beat clock. Deadlines advance by period, so late redraws do not drift."""
    def __init__(self, bpm=120, meter=4):
        if meter not in METERS:
            raise ValueError('meter must be 2, 3, 4, or 6 (6/8).')
        self.bpm = max(MIN_BPM, min(MAX_BPM, int(round(bpm))))
        self.meter = meter
        self.running = False
        self.ever_started = False
        self.beat_index = 0
        self.next_tick = None
        self.last_tick = None
        self.pulse_until = 0.0

    @property
    def period(self):
        return 60.0 / self.bpm

    def pulse_on(self, now):
        return self.running and now < self.pulse_until

    def advance(self, now):
        if not self.running or now < self.next_tick:
            return
        period = self.period
        steps = int(math.floor((now - self.next_tick) / period)) + 1
        self.beat_index = (self.beat_index + steps) % self.meter
        self.last_tick = self.next_tick + (steps - 1) * period
        self.next_tick += steps * period
        self.pulse_until = self.last_tick + min(0.12, period * 0.45)

    def start(self, now):
        self.running = self.ever_started = True
        self.beat_index = 0
        self.last_tick = now
        self.next_tick = now + self.period
        self.pulse_until = now + min(0.12, self.period * 0.45)

    def pause(self):
        self.running = False
        self.next_tick = None
        self.pulse_until = 0.0

    def toggle(self, now):
        if self.running:
            self.pause()
        else:
            self.start(now)

    def set_bpm(self, value, now):
        value = max(MIN_BPM, min(MAX_BPM, int(round(value))))
        if value == self.bpm:
            return
        self.advance(now)
        old_period = self.period
        remaining = max(0.0, min(1.0, (self.next_tick - now) / old_period)) if self.running else 1.0
        self.bpm = value
        if self.running:
            self.next_tick = now + remaining * self.period
            self.last_tick = self.next_tick - self.period
            self.pulse_until = self.last_tick + min(0.12, self.period * 0.45)

    def set_meter(self, value, now):
        if value not in METERS:
            raise ValueError('Unsupported meter.')
        if value != self.meter:
            self.meter = value
            self.beat_index = 0
            if self.running:
                self.start(now)



    def reset(self):
        self.__init__()


BUTTONS = {
    'exit': (744, 12, 776, 54),
    'minus': (44, 164, 112, 232), 'plus': (384, 164, 452, 232),
    'slider': (44, 268, 452, 312),
    'meter_2': (508, 140, 628, 198), 'meter_3': (636, 140, 756, 198),
    'meter_4': (508, 208, 628, 266), 'meter_6': (636, 208, 756, 266),
    'toggle': (24, 406, 624, 468), 'reset': (640, 406, 776, 468),
}


def _inside(bounds, x, y):
    x0, y0, x1, y1 = bounds
    return x0 <= x < x1 and y0 <= y < y1


class MetronomeUI:
    """Touch UI using existing lcd/touch objects. run() blocks until Exit/Ctrl+C.

    A tap fires once per contact. Slider dragging and +/- long-press repeat are
    supported. The user's verified raw x/y mapping is used directly.
    Exit pauses the visual metronome and retains the externally owned devices.
    """
    def __init__(self, lcd, touch, bpm=120, meter=4, clock=None):
        if lcd.frame is None or not lcd.running:
            raise RuntimeError('Start the LCD first: lcd.start().')
        if lcd.frame.shape != (HEIGHT, WIDTH, 3) or lcd.frame.dtype != np.uint8:
            raise ValueError('Expected an 800x480 uint8 BGR framebuffer.')
        self.lcd, self.touch = lcd, touch
        self._owner = lcd.frame
        self._display = np.asarray(lcd.frame)
        self.canvas = Canvas()
        self.state = MetronomeState(bpm, meter)
        self.clock = clock or time.monotonic
        self.closed = False
        self._active = False
        self.ui_stats = False
        self._timings = {k:deque(maxlen=4096) for k in ('touch','step','paint','render','copy_flush','loop')}
        self._down = False
        self._contact_id = None
        self._pressed = None
        self._hold_since = 0.0
        self._repeat_at = 0.0
        self._last_contact = 0.0
        self._last_key = None
        self._last_paint = float('-inf')

    def _slider(self, x, now):
        fraction = max(0.0, min(1.0, (x - 62) / 372.0))
        self.state.set_bpm(MIN_BPM + fraction * (MAX_BPM - MIN_BPM), now)

    def _action(self, name, x, now):
        if name == 'minus':
            self.state.set_bpm(self.state.bpm - 1, now)
        elif name == 'plus':
            self.state.set_bpm(self.state.bpm + 1, now)
        elif name == 'slider':
            self._slider(x, now)
        elif name.startswith('meter_'):
            self.state.set_meter(int(name.split('_')[1]), now)
        elif name == 'toggle':
            self.state.toggle(now)
        elif name == 'reset':
            self.state.reset()
        elif name == 'exit':
            self.stop()

    def _touch_report(self, points, now):
        if points is None:  # No new report does not mean finger released.
            return
        if not points:
            self._down = False
            self._contact_id = None
            self._pressed = None
            return
        if not self._down:
            self._down = True
            self._contact_id = points[0]['id']
            p = points[0]
            x, y = int(p['x']), int(p['y'])
            self._pressed = next((key for key, bounds in BUTTONS.items()
                                  if _inside(bounds, x, y)), None)
            self._hold_since = self._last_contact = now
            self._repeat_at = now + 0.45
            if self._pressed:
                self._action(self._pressed, x, now)
            return
        p = next((item for item in points if item['id'] == self._contact_id), None)
        if p is None:
            self._pressed = None
            return
        self._last_contact = now
        x, y = int(p['x']), int(p['y'])
        if self._pressed == 'slider':
            if 235 <= y <= 312:
                self._slider(x, now)
            else:
                self._pressed = None
        elif self._pressed and not _inside(BUTTONS[self._pressed], x, y):
            self._pressed = None

    def _repeat(self, now):
        if (self._down and self._pressed in ('minus', 'plus') and
                now >= self._repeat_at and now - self._last_contact < 0.8):
            amount = 5 if now - self._hold_since >= 2.0 else 1
            if self._pressed == 'minus':
                amount = -amount
            self.state.set_bpm(self.state.bpm + amount, now)
            self._repeat_at = now + 0.12

    def _key(self, now):
        s = self.state
        return (s.bpm, s.meter, s.running, s.ever_started, s.beat_index,
                s.pulse_on(now), self._pressed, self.closed)


    def paint(self, now=None):
        now = self.clock() if now is None else now
        if self.lcd.frame is not self._owner or not self.lcd.running:
            raise RuntimeError('LCD framebuffer changed or stopped; create a new UI after starting LCD.')
        started=time.perf_counter()
        self.render(now)
        rendered=time.perf_counter()
        # Only this whole-frame copy touches the live PynqBuffer.
        np.copyto(self._display, self.canvas.image)
        self.lcd.frame.flush()
        self._last_key = self._key(now)
        self._last_paint = now
        if self.ui_stats:
            ended=time.perf_counter()
            self._timings['paint'].append((ended-started)*1000)
            self._timings['render'].append((rendered-started)*1000)
            self._timings['copy_flush'].append((ended-rendered)*1000)

    def render(self, now):
        if not isinstance(self.canvas, DashboardCanvas):
            self.canvas = DashboardCanvas()
        self.canvas.image[:] = C['background']
        self.canvas.text('title', 43, 20, C['ink'])
        _draw_metronome(self.canvas, self.state, self._pressed, now)
        return self.canvas.image


    def step(self, now, points=None):
        self.state.advance(now)
        self._touch_report(points, now)
        self._repeat(now)
        key = self._key(now)
        if key != self._last_key and (self.closed or now - self._last_paint >= 0.05):
            self.paint(now)

    def stop(self):
        self.state.pause()
        self.closed = True

    def run(self):
        if self._active:
            raise RuntimeError('This UI is already running.')
        self.closed=False;self._down=False;self._pressed=None
        self._last_key=None;self._active=True
        next_poll=0.;report_at=self.clock()+5.;previous=self.clock()
        try:
            self.paint()
            while not self.closed:
                now=self.clock();points=None
                if self.ui_stats:self._timings['loop'].append((now-previous)*1000)
                previous=now
                if now>=next_poll:
                    started=time.perf_counter()
                    points=self.touch.read_points()
                    if self.ui_stats:self._timings['touch'].append((time.perf_counter()-started)*1000)
                    now=self.clock();next_poll=now+.010
                started=time.perf_counter()
                self.step(now,points)
                if self.ui_stats:
                    self._timings['step'].append((time.perf_counter()-started)*1000)
                    if self.clock()>=report_at:
                        report={}
                        for key,values in self._timings.items():
                            a=np.asarray(values,dtype=float)
                            report[key+'_p95_ms']=round(float(np.percentile(a,95)),1) if len(a) else None
                            report[key+'_max_ms']=round(float(a.max()),1) if len(a) else None
                            if key=='paint':report['frame_writes_5s']=len(a)
                            values.clear()
                        print('UI_TIMING: '+json.dumps(report),flush=True)
                        report_at=self.clock()+5.
                time.sleep(.002)
        except KeyboardInterrupt:
            pass
        finally:
            self._active=False;self.stop();self._down=False;self._pressed=None
            if self.lcd.frame is self._owner and self.lcd.running:self.paint()
        return self



# Appended to the tested metronome implementation when building music_dashboard.py.
from dataclasses import dataclass, asdict, replace
from datetime import datetime, timezone, timedelta
from pathlib import Path
import threading

NAV = {
    'nav_home': (330, 12, 402, 54), 'nav_metronome': (408, 12, 486, 54),
    'nav_spectrum': (492, 12, 570, 54), 'nav_notation': (576, 12, 654, 54),
    'nav_instrument': (660, 12, 738, 54), 'exit': BUTTONS['exit'],
}
HOME_CARDS = {
    'nav_metronome': (24, 182, 392, 310), 'nav_spectrum': (408, 182, 776, 310),
    'nav_notation': (24, 326, 392, 454), 'nav_instrument': (408, 326, 776, 454),
}
SPECTRUM_BUTTONS = {
    'range_2000': (24, 412, 144, 468), 'range_5000': (156, 412, 276, 468),
    'range_8000': (288, 412, 408, 468), 'freeze': (424, 412, 576, 468),
    'clear_spectrum': (592, 412, 776, 468),
}
NOTATION_BUTTONS = {
    'record': (24, 424, 204, 468), 'latest': (216, 424, 384, 468),
    'save': (396, 424, 564, 468), 'clear_notes': (576, 424, 776, 468),
}
_UNSET = object()


@dataclass(frozen=True)
class Note:
    """Numbered note relative to 1=C. octave=0 is the C4..B4 register."""
    degree: int
    octave: int = 0
    accidental: int = 0
    beats: float = 1.0
    frequency: object = None
    confidence: object = None
    note_name: object = None
    note_id: object = None
    bar_end: bool = False

    def __post_init__(self):
        if self.degree not in range(8) or int(self.degree) != self.degree:
            raise ValueError('degree must be 0 (rest) or 1..7.')
        if self.octave not in range(-4, 5) or int(self.octave) != self.octave:
            raise ValueError('octave must be -4..4.')
        if self.accidental not in (-1, 0, 1):
            raise ValueError('accidental must be -1, 0, or 1.')
        if self.beats not in (0.125, 0.1875, 0.25, 0.375, 0.5, 0.75, 1, 1.5, 2, 3, 4, 6, 8):
            raise ValueError('beats must be a supported quantized note duration.')
        if self.frequency is not None and (not math.isfinite(self.frequency) or self.frequency <= 0):
            raise ValueError('frequency must be positive Hz, or None.')
        if self.confidence is not None and (not math.isfinite(self.confidence) or not 0 <= self.confidence <= 1):
            raise ValueError('confidence must be 0..1, or None.')
        for field in ('degree', 'octave', 'accidental'):
            object.__setattr__(self, field, int(getattr(self, field)))
        object.__setattr__(self, 'beats', float(self.beats))
        object.__setattr__(self, 'bar_end', bool(self.bar_end))
        for field in ('frequency', 'confidence'):
            if getattr(self, field) is not None:
                object.__setattr__(self, field, float(getattr(self, field)))
        if self.note_id is not None:
            object.__setattr__(self, 'note_id', str(self.note_id))
        if self.note_name is not None:
            object.__setattr__(self, 'note_name', str(self.note_name)[:16])

    @property
    def identity(self):
        return (self.degree, self.octave, self.accidental, self.note_id)


@dataclass(frozen=True)
class Spectrum:
    frequencies: object
    relative_db: object
    has_signal: bool


def _spectrum_packet(frequencies, magnitudes, db=False):
    if np.iscomplexobj(frequencies) or np.iscomplexobj(magnitudes):
        raise ValueError('Provide real frequencies and FFT magnitudes, e.g. abs(fft_values).')
    f = np.array(frequencies, dtype=np.float64, copy=True)
    a = np.array(magnitudes, dtype=np.float64, copy=True)
    if f.ndim != 1 or a.ndim != 1 or len(f) != len(a) or len(f) < 2:
        raise ValueError('Spectrum requires two equally sized 1-D arrays, length >= 2.')
    if not np.isfinite(f).all() or not np.isfinite(a).all():
        raise ValueError('Spectrum values must be finite.')
    if f[0] < 0 or np.any(np.diff(f) <= 0):
        raise ValueError('Frequencies must be nonnegative and strictly increasing, in Hz.')
    if db:
        levels = a - float(a.max())
        has_signal = True
    else:
        if np.any(a < 0):
            raise ValueError('Linear magnitudes must be nonnegative.')
        peak = float(a.max())
        has_signal = peak > 0
        levels = 20 * np.log10(np.maximum(a / peak, 1e-6)) if has_signal else np.full_like(a, -60)
    levels = np.clip(levels, -60, 0)
    f.flags.writeable = levels.flags.writeable = False
    return Spectrum(f, levels, has_signal)


class DashboardCanvas(Canvas):
    def blit(self, alpha, x, y, colour, clip=None):
        height, width = alpha.shape
        bx0, by0, bx1, by1 = clip or (0, 0, WIDTH, HEIGHT)
        x, y = int(x), int(y)
        x0, y0 = max(0, bx0, x), max(0, by0, y)
        x1, y1 = min(WIDTH, bx1, x + width), min(HEIGHT, by1, y + height)
        if x1 <= x0 or y1 <= y0:
            return
        a = alpha[y0-y:y1-y, x0-x:x1-x, None].astype(np.uint16)
        roi = self.image[y0:y1, x0:x1]
        roi[:] = ((roi.astype(np.uint16) * (255-a) + np.asarray(colour, dtype=np.uint16) * a + 127) // 255).astype(np.uint8)

    def ascii(self, value, x, y, colour, size=14, centered=False):
        value = str(value)
        advance = int(math.ceil(size * 0.6))
        height = _assets()['ascii{}_65'.format(size)][2]
        if centered:
            x, y = x - len(value) * advance / 2, y - height / 2
        for char in value:
            key = 'ascii{}_{}'.format(size, ord(char) if 32 <= ord(char) <= 126 else 63)
            self.text(key, x - 4, y, colour)
            x += advance

    def line(self, x0, y0, x1, y1, colour, width=1):
        count = int(max(abs(x1-x0), abs(y1-y0))) + 1
        x = np.rint(np.linspace(x0, x1, count)).astype(int)
        y = np.rint(np.linspace(y0, y1, count)).astype(int)
        for offset in range(-(width // 2), width - width // 2):
            yy = np.clip(y + offset, 0, HEIGHT-1)
            self.image[yy, np.clip(x, 0, WIDTH-1)] = colour

    def note(self, note, cx, cy, size, colour, rhythm=False, clip=None):
        if note is None:
            self.ascii('--',cx,cy,C['muted'],32,True)
            return
        clip=clip or (0,0,WIDTH,HEIGHT)
        alpha=_note_alpha(int(note.degree),int(size))
        height,width=alpha.shape
        self.blit(alpha,cx-width/2,cy-height/2,colour,clip)
        if note.degree and note.accidental:
            key='ascii{}_{}'.format(22 if size>40 else 14,35 if note.accidental>0 else 98)
            mask,w,h=_assets()[key]
            self.blit(mask,cx-width/2-w+3,cy-h/2,colour,clip)
        radius=2 if size>40 else 1
        spacing=4 if size>40 else 2
        if note.degree:
            for index in range(abs(note.octave)):
                yy=cy+(height/2+3+index*spacing)*(1 if note.octave<0 else -1)
                if clip[0]+radius<=cx<clip[2]-radius and clip[1]+radius<=yy<clip[3]-radius:
                    self.circle(int(cx),int(yy),radius,colour)
        if rhythm:
            flags,dotted=_rhythm(note.beats)
            underline=int(cy+height/2+5+max(0,-note.octave)*2)
            for i in range(flags):self.clipped_rect((int(cx)-9,underline+i*2,int(cx)+10,underline+i*2+1),colour,clip)
            if dotted:
                px,py=int(cx+width/2+5),int(cy+2)
                if clip[0]+1<=px<clip[2]-1 and clip[1]+1<=py<clip[3]-1:self.circle(px,py,1,colour)


    def clipped_rect(self, bounds, colour, clip):
        x0,y0,x1,y1=bounds
        x0,y0,x1,y1=max(x0,clip[0]),max(y0,clip[1]),min(x1,clip[2]),min(y1,clip[3])
        if x1>x0 and y1>y0:self.rect((int(x0),int(y0),int(x1),int(y1)),colour)

    def ellipse(self, bounds, colour):
        x0,y0,x1,y1=map(int,bounds)
        x0,y0,x1,y1=max(0,x0),max(0,y0),min(WIDTH,x1),min(HEIGHT,y1)
        if x1<=x0 or y1<=y0:return
        yy,xx=np.ogrid[:y1-y0,:x1-x0]
        mask=((xx-(x1-x0-1)/2)/max(1,(x1-x0)/2))**2+((yy-(y1-y0-1)/2)/max(1,(y1-y0)/2))**2<=1
        self.image[y0:y1,x0:x1][mask]=colour

    def polygon(self, points, colour):
        points=np.asarray(points,dtype=float)
        x0=max(0,int(np.floor(points[:,0].min())));x1=min(WIDTH,int(np.ceil(points[:,0].max()))+1)
        y0=max(0,int(np.floor(points[:,1].min())));y1=min(HEIGHT,int(np.ceil(points[:,1].max()))+1)
        yy,xx=np.ogrid[y0:y1,x0:x1];mask=np.zeros((y1-y0,x1-x0),dtype=bool)
        for i in range(len(points)):
            a,b=points[i],points[(i+1)%len(points)]
            if a[1]==b[1]:continue
            mask^=((a[1]>yy)!=(b[1]>yy))&(xx<(b[0]-a[0])*(yy-a[1])/(b[1]-a[1])+a[0])
        self.image[y0:y1,x0:x1][mask]=colour



@lru_cache(maxsize=128)
def _note_alpha(degree, size):
    alpha = _assets()['note72_' + str(degree)][0]
    if size == 72:
        return alpha
    height = max(1, int(round(alpha.shape[0] * size / 72)))
    width = max(1, int(round(alpha.shape[1] * size / 72)))
    yy = np.linspace(0, alpha.shape[0]-1, height)
    xx = np.linspace(0, alpha.shape[1]-1, width)
    y0, x0 = yy.astype(int), xx.astype(int)
    y1, x1 = np.minimum(y0+1, alpha.shape[0]-1), np.minimum(x0+1, alpha.shape[1]-1)
    wy, wx = (yy-y0)[:, None], (xx-x0)[None, :]
    return ((alpha[y0[:, None], x0[None, :]]*(1-wy)*(1-wx)) +
            (alpha[y1[:, None], x0[None, :]]*wy*(1-wx)) +
            (alpha[y0[:, None], x1[None, :]]*(1-wy)*wx) +
            (alpha[y1[:, None], x1[None, :]]*wy*wx)).astype(np.uint16)


def _rhythm(beats):
    dotted = beats in (0.1875, 0.375, 0.75, 1.5)
    base = beats / 1.5 if dotted else beats
    flags = max(0, int(round(-math.log(base, 2)))) if base < 1 else 0
    return flags, dotted


class MusicDashboardUI(MetronomeUI):
    """Home + metronome + spectrum + scrolling numbered notation.

    Producers may call update_spectrum/update_note/commit_note from another
    Python thread. Current/spectrum updates coalesce; finalized notes do not.
    demo=False is the real-data default; demo=True is explicitly labeled.
    """
    def __init__(self, lcd, touch, demo=False, record_dir='music_records', clock=None):
        super().__init__(lcd, touch, clock=clock)
        self.canvas = DashboardCanvas()
        self.page = 'home'
        self.demo = bool(demo)
        self.record_dir = Path(record_dir)
        self._lock = threading.Lock()
        self._pending_current = self._pending_spectrum = _UNSET
        self._producer_current = None
        self._pending_commits = deque()
        self.current_note = None
        self._held_note = None
        self._held_until = 0.0
        self.recent_notes = deque(maxlen=6)
        self.records = []
        self._tokens = []
        self._seen_ids = set()
        self.recording = True
        self.score_page = 0
        self.score_scroll = 0.0
        self.instrument_label = None
        self.follow_latest = True
        self.spectrum = None
        self._spectrum_version = 0
        self._spectrum_at = float('-inf')
        self.spectrum_range = 8000
        self.spectrum_frozen = False
        self._frozen_spectrum = None
        self._frozen_version = 0
        self._clear_until = 0.0
        self._notice = None
        self._notice_until = 0.0
        self.last_saved_path = None
        self.last_error = None
        self._demo_feed = _DemoFeed() if self.demo else None

    def _real_input(self):
        if self.demo:
            raise RuntimeError('Create MusicDashboardUI(..., demo=False) for actual recognition data.')

    def update_spectrum(self, frequencies, magnitudes, db=False):
        """Hz axis + magnitudes; chart is normalized to a relative 0..-60 dB."""
        self._real_input()
        packet = _spectrum_packet(frequencies, magnitudes, db)
        with self._lock:
            self._pending_spectrum = packet

    def update_note(self, degree, **values):
        """Update only the live note. degree=None means currently no detected note."""
        self._real_input()
        note = None if degree is None else Note(degree, **values)
        with self._lock:
            self._producer_current = note
            self._pending_current = note

    def commit_note(self, degree=None, **values):
        """Append a finalized note. Optional note_id suppresses duplicate commits.

        With degree omitted, snapshot the most recently published live note.
        Repeated pitches without note_id remain distinct finalized notes.
        """
        self._real_input()
        with self._lock:
            if degree is None:
                if self._producer_current is None:
                    raise ValueError('No live note to finalize; provide degree explicitly.')
                note = replace(self._producer_current, **values)
            else:
                note = Note(degree, **values)
            if len(self._pending_commits) >= 2048:
                raise BufferError('Finalized-note queue full; existing notes retained. Drain the UI, then retry this commit.')
            self._pending_commits.append(note)

    def _drain(self, now):
        with self._lock:
            current, spectrum = self._pending_current, self._pending_spectrum
            commits = list(self._pending_commits)
            self._pending_current = self._pending_spectrum = _UNSET
            self._pending_commits.clear()
        if spectrum is not _UNSET:
            self._receive_spectrum(spectrum, now)
        if current is not _UNSET:
            self._receive_current(current, now)
        for note in commits:
            if self.current_note is None:
                self._held_note,self._held_until=note,now+.7
            self._record(note)

    def _receive_spectrum(self, packet, now):
        self.spectrum = packet
        self._spectrum_at = now
        self._spectrum_version += 1

    def _receive_current(self, note, now):
        old = self.current_note
        if old is not None and (note is None or old.identity != note.identity):
            self.recent_notes.append(old)
        self.current_note = note
        if note is not None:self._held_note,self._held_until=note,now+.7

    def _display_note(self,now):
        return self.current_note or (self._held_note if now<self._held_until else None)

    def _record(self, note):
        if note.note_id is not None:
            if note.note_id in self._seen_ids:
                return
            self._seen_ids.add(note.note_id)
        if not self.recording:
            return
        self.records.append(note)
        self._tokens.append(('note', note))
        if note.beats >= 2:
            self._tokens.extend(('dash', None) for _ in range(int(note.beats)-1))
        if note.bar_end:
            self._tokens.append(('bar', None))
        if self.follow_latest:
            self.score_page = self.page_count - 1
            self.score_scroll = self._max_score_scroll()

    @property
    def page_count(self):
        return max(1, (len(self._tokens)+47)//48)

    def _buttons(self):
        result = dict(NAV)
        if self.page == 'home':
            result.update({key + '_card': bounds for key, bounds in HOME_CARDS.items()})
        elif self.page == 'metronome':
            result.update({key: bounds for key, bounds in BUTTONS.items() if key != 'exit'})
        elif self.page == 'spectrum':
            result.update(SPECTRUM_BUTTONS)
        elif self.page == 'notation':
            result.update(NOTATION_BUTTONS)
        return result

    def _action(self, name, x, now):
        if name.startswith('nav_'):
            self.page = name[4:].replace('_card', '')
            self._clear_until = 0.0
        elif name == 'exit':
            self.stop()
        elif self.page == 'metronome':
            super()._action(name, x, now)
        elif self.page == 'spectrum':
            if name.startswith('range_'):
                self.spectrum_range = int(name[6:])
            elif name == 'freeze':
                self.spectrum_frozen = not self.spectrum_frozen
                if self.spectrum_frozen:
                    self._frozen_spectrum = self.spectrum
                    self._frozen_version = self._spectrum_version
            elif name == 'clear_spectrum':
                self.spectrum = self._frozen_spectrum = None
                self._spectrum_version += 1
                self._frozen_version = self._spectrum_version
        elif self.page == 'notation':
            if name == 'record':
                self.recording = not self.recording
            elif name == 'previous':
                self.score_page = max(0, self.score_page-1)
                self.follow_latest = False
            elif name == 'next':
                self.score_page = min(self.page_count-1, self.score_page+1)
                self.follow_latest = False
            elif name == 'latest':
                self.follow_latest = True
                self.score_page = self.page_count-1
                self.score_scroll = self._max_score_scroll()
            elif name == 'save':
                self.save_records(now=now)
            elif name == 'clear_notes':
                if now < self._clear_until:
                    self.records.clear()
                    self._tokens.clear()
                    self._seen_ids.clear()
                    self.score_page = 0
                    self.score_scroll = 0.0
                    self.follow_latest = True
                    self._clear_until = 0
                    self._toast('cleared', now)
                else:
                    self._clear_until = now + 3

    def _touch_report(self, points, now):
        if points is None:
            return
        if not points:
            if self._down:
                x, y = self._touch_last
                dx, dy = x-self._touch_start[0], y-self._touch_start[1]
                pressed = self._pressed
                if not self._touch_control and abs(dx) >= 80 and abs(dx) > abs(dy)*1.3:
                    pages = ('home', 'metronome', 'spectrum', 'notation', 'instrument')
                    index = pages.index(self._touch_page)
                    self.page = pages[max(0, min(len(pages)-1, index+(1 if dx < 0 else -1)))]
                    self._clear_until = 0
                elif (not self._touch_moved and not self._touch_control and pressed and
                      _inside(self._buttons().get(pressed, (0,0,0,0)), x, y)):
                    self._action(pressed, x, now)
            self._down = False
            self._pressed = self._contact_id = None
            return
        if not self._down:
            p = points[0]
            x, y = int(p['x']), int(p['y'])
            self._down, self._contact_id = True, p['id']
            self._touch_start = self._touch_last = (x, y)
            self._touch_page, self._touch_scroll = self.page, self.score_scroll
            self._touch_moved = False
            self._pressed = next((key for key,b in self._buttons().items() if _inside(b,x,y)), None)
            self._touch_control = self.page == 'metronome' and self._pressed in ('slider','minus','plus')
            self._hold_since = self._last_contact = now
            self._repeat_at = now+.45
            if self._touch_control:
                self._action(self._pressed, x, now)
            return
        p = next((v for v in points if v['id'] == self._contact_id), None)
        if p is None:
            self._pressed = None
            self._touch_moved = True
            return
        x, y = int(p['x']), int(p['y'])
        self._touch_last, self._last_contact = (x,y), now
        dx, dy = x-self._touch_start[0], y-self._touch_start[1]
        if self._touch_control:
            if self._pressed == 'slider':
                self._slider(x, now)
            elif self._pressed and not _inside(BUTTONS[self._pressed], x, y):
                self._pressed = None
            return
        if abs(dx) > 24 or abs(dy) > 24:
            self._touch_moved = True
            self._pressed = None
        if (self._touch_page == 'notation' and 264 <= self._touch_start[1] < 416 and
                abs(dy) > 24 and abs(dy) > abs(dx)):
            self.score_scroll = max(0., min(self._max_score_scroll(), self._touch_scroll-dy))
            self.follow_latest = False
            self.score_page = int(self.score_scroll/(48*3))


    def _toast(self, name, now):
        self._notice, self._notice_until = name, now + 2.5

    def save_records(self, path=None, now=None):
        now = self.clock() if now is None else now
        if not self.records:
            self._toast('nothing_to_save', now)
            return None
        stamp = datetime.now(timezone(timedelta(hours=8)))
        path = Path(path) if path is not None else self.record_dir / ('jianpu_' + stamp.strftime('%Y%m%d_%H%M%S_%f') + '.json')
        data = {'format': 'ac820-numbered-notes-v1', 'mode': 'demo' if self.demo else 'live',
                'key': '1=C', 'created_at': stamp.isoformat(),
                'bpm': self.state.bpm, 'meter': str(self.state.meter) + ('/8' if self.state.meter == 6 else '/4'),
                'notes': [asdict(note) for note in self.records]}
        try:
            path.parent.mkdir(parents=True, exist_ok=True)
            # Exclusive creation prevents accidental replacement of earlier records.
            with path.open('x', encoding='utf-8') as stream:
                json.dump(data, stream, ensure_ascii=False, indent=2)
        except OSError as error:
            self.last_error = str(error)
            self._toast('save_failed', now)
            print('Music records save failed:', error)
            return None
        self.last_saved_path = str(path)
        self._toast('saved', now)
        print('Music records saved:', path)
        return str(path)

    def _visible_spectrum(self):
        return self._frozen_spectrum if self.spectrum_frozen else self.spectrum

    def _peak(self):
        packet = self._visible_spectrum()
        if packet is None or not packet.has_signal:
            return None
        valid = (packet.frequencies > 0) & (packet.frequencies <= self.spectrum_range)
        if not valid.any():
            return None
        indices = np.flatnonzero(valid)
        index = indices[np.argmax(packet.relative_db[valid])]
        return float(packet.frequencies[index])

    def _key(self, now):
        common=(self.page,self.closed,self._pressed,self.demo,self._notice if now<self._notice_until else None,self.state.running)
        if self.page=='metronome':return common+super()._key(now)
        if self.page=='home':return common+(self.state.bpm,len(self.records),self._peak(),getattr(self,'instrument_label',None))
        if self.page=='instrument':return common+(getattr(self,'instrument_label',None),)
        if self.page=='spectrum':
            return common+(self.spectrum_range,self.spectrum_frozen,self._frozen_version if self.spectrum_frozen else self._spectrum_version,now-self._spectrum_at>2)
        n=self._display_note(now);current=None if n is None else (n.identity,n.note_name,n.frequency)
        return common+(current,self.current_note is not None,len(self.records),round(self.score_scroll),self.follow_latest,self.recording,now<self._clear_until)


    def step(self, now, points=None):
        self._drain(now)
        if self._demo_feed is not None:
            self._demo_feed.tick(self, now)
        self.state.advance(now)
        self._touch_report(points, now)
        if self.page == 'metronome':
            self._repeat(now)
        if self._key(now) != self._last_key and (self.closed or now-self._last_paint >= 1/15):
            self.paint(now)

    def _header(self):
        c = self.canvas
        c.rect((0,0,WIDTH,86), C['background'])
        c.rounded((24,20,30,48),3,C['accent'])
        title = {'home':'home_title','metronome':'title','spectrum':'spectrum_title',
                 'notation':'notation_title','instrument':'instrument_title'}[self.page]
        c.text(title,43,20,C['ink'])
        for key,bounds in NAV.items():
            selected = key[4:] == self.page
            c.rounded(bounds,11,C['selected'] if selected else C['white'],None if selected else C['line'])
            c.text('exit' if key == 'exit' else key,(bounds[0]+bounds[2])//2,33,
                   C['background'] if selected else C['muted'],True)
            if key == 'nav_metronome' and self.state.running:
                c.circle(bounds[2]-8,bounds[1]+8,2,C['accent'])
        label = getattr(self,'model_label','Instrument: --')
        c.ascii(label,776-len(label)*9,63,C['accent'],14)
        c.line(24,84,776,84,C['line'])


    def _badge(self, x, y, text, colour='accent', width=104):
        c = self.canvas
        fill = 'accent_light' if colour == 'accent' else ('green_light' if colour == 'green' else 'soft')
        c.rounded((x, y, x+width, y+26), 13, C[fill])
        c.text(text, x+width//2, y+13, C[colour], True)

    def _home(self):
        c = self.canvas
        c.rounded((24,96,776,166),18,C['white'],C['line'])
        c.text('welcome',44,119,C['ink'])
        self._badge(650,116,'live_data' if getattr(self,'source_label','') == 'SPEC LIVE' else 'waiting_data',
                    'green' if getattr(self,'source_label','') == 'SPEC LIVE' else 'muted',104)
        for key,b in HOME_CARDS.items():
            c.rounded(b,18,C['white'],C['accent'] if self._pressed == key+'_card' else C['line'])
            cx,cy = b[0]+53,b[1]+58
            c.rounded((cx-29,cy-29,cx+30,cy+30),15,C['soft'])
            if key == 'nav_metronome':
                c.line(cx-17,cy+18,cx-3,cy-21,C['accent'],3)
                c.line(cx-3,cy-21,cx+19,cy+18,C['accent'],3)
                c.line(cx-17,cy+18,cx+19,cy+18,C['accent'],3)
                c.line(cx,cy+12,cx+15,cy-16,C['ink'],2);c.circle(cx+15,cy-16,3,C['accent'])
                text,value='home_metronome',str(self.state.bpm)+' BPM'
            elif key == 'nav_spectrum':
                for i,h in enumerate((13,27,40,25,18)):
                    c.rounded((cx-21+i*9,cy+19-h,cx-16+i*9,cy+19),2,C['accent'] if i==2 else C['blue'])
                peak=self._peak();text,value='home_spectrum','-- Hz' if peak is None else '{:.0f} Hz'.format(peak)
            elif key == 'nav_notation':
                for i,d in enumerate((1,2,3)):c.note(Note(d),cx-17+i*17,cy,22,C['accent'])
                text,value='home_notation',str(len(self.records))
            else:
                c.line(cx-17,cy+13,cx+15,cy-15,C['accent'],3)
                c.circle(cx-11,cy+12,7,C['accent']);c.circle(cx+17,cy+12,7,C['blue'])
                text,value='home_instrument',self._instrument_name()
            c.text(text,b[0]+101,b[1]+29,C['ink'])
            if key == 'nav_instrument':
                c.text(value,b[0]+101,b[1]+74,C['muted'])
            else:c.ascii(value,b[0]+101,b[1]+73,C['muted'],22)
            c.ascii('>',b[2]-30,b[1]+53,C['accent'],22)


    def _spectrum_page(self, now):
        c = self.canvas
        c.rounded((24,96,776,400),18,C['white'],C['line'])
        c.text('spectrum_live',44,114,C['ink'])
        x0,x1,y0,y1 = 60,748,150,354
        packet = self._visible_spectrum()
        levels = np.full(64,-60.,dtype=float)
        if packet is not None and packet.has_signal:
            mask=(packet.frequencies>=0)&(packet.frequencies<=self.spectrum_range)
            bins=np.minimum(63,(packet.frequencies[mask]*64/self.spectrum_range).astype(int))
            np.maximum.at(levels,bins,packet.relative_db[mask])
        self._bar_levels = levels.copy()
        segments=np.clip(np.ceil((levels+60)/60*34).astype(int),0,34)
        yy=np.arange(y1-y0)[:,None]
        xx=np.arange(x1-x0)[None,:]
        bar_index=np.minimum(63,(xx*64/(x1-x0)).astype(int))
        offset=(xx*64)%(x1-x0)/(x1-x0)
        height_index=(y1-y0-1-yy)//6
        active=(height_index<segments[bar_index])&(offset<.64)&(((y1-y0-1-yy)%6)<4)
        low=np.array(_colour('#77A8FF'));middle=np.array(_colour('#D3DCEB'));high=np.array(_colour('#EF9C80'))
        t=np.linspace(1.,0.,y1-y0)[:,None]
        rgb=np.where(t<.55,low+(middle-low)*t/.55,middle+(high-middle)*(t-.55)/.45)
        colour=np.clip(rgb,0,255).astype('u1')[:,None,:]
        roi=c.image[y0:y1,x0:x1];roi[active]=np.broadcast_to(colour,roi.shape)[active]
        c.line(x0,y1+2,x1,y1+2,C['line'])
        for i in range(5):
            value=int(self.spectrum_range*i/4);text=str(value) if value<1000 else '{:g}k'.format(value/1000)
            c.ascii(text,x0+int((x1-x0)*i/4),365,C['muted'],14,True)
        peak=self._peak()
        c.ascii('-- Hz' if peak is None else '{:.1f} Hz'.format(peak),44,113+264,C['ink'],14)
        for limit in (2000,5000,8000):
            b=SPECTRUM_BUTTONS['range_'+str(limit)];selected=self.spectrum_range==limit
            c.rounded(b,14,C['selected'] if selected else C['white'],None if selected else C['line'])
            c.text('range_'+str(limit),(b[0]+b[2])//2,440,C['background'] if selected else C['muted'],True)
        for key,text in [('freeze','resume' if self.spectrum_frozen else 'freeze'),('clear_spectrum','clear_graph')]:
            b=SPECTRUM_BUTTONS[key];c.rounded(b,14,C['white'],C['line'])
            c.text(text,(b[0]+b[2])//2,440,C['ink'],True)


    def _notation_page(self, now):
        c=self.canvas
        c.rounded((24,96,776,218),18,C['white'],C['line'])
        c.text('recognizing',44,109,C['muted'])
        # Only past notes precede the current note; no moving/future glyphs.
        displayed=self._display_note(now)
        history=[n for n in self.recent_notes if displayed is None or n.identity!=displayed.identity][-3:]
        for i,note in enumerate(history):
            x=(78,164,250)[3-len(history)+i]
            c.note(note,x,164,28,C['muted'],clip=(42,134,310,213))
        c.rounded((342,106,466,210),14,C['accent_light'])
        c.text('current' if self.current_note else 'latest',404,113,C['accent'],True)
        c.note(displayed,404,164,72,C['accent'],clip=(346,130,462,210))
        note=displayed
        c.ascii((note.note_name or '--') if note else '--',614,145,C['ink'],32,True)
        c.ascii('-- Hz' if note is None or note.frequency is None else '{:.1f} Hz'.format(note.frequency),
                614,187,C['muted'],14,True)
        c.rounded((24,230,776,414),18,C['white'],C['line'])
        c.text('recognized_score',44,240,C['ink'])
        c.ascii('1=C',230,240,C['muted'],14)
        c.ascii(str(len(self.records)),728,240,C['muted'],14)
        self.score_scroll=max(0.,min(self._max_score_scroll(),self.score_scroll))
        clip=(42,266,752,410)
        if not self._tokens:
            c.text('score_empty',400,333,C['muted'],True)
        else:
            first=max(0,int(self.score_scroll//48))
            last=first+4
            for row in range(first,last):
                for col in range(16):
                    index=row*16+col
                    if index>=len(self._tokens):break
                    kind,value=self._tokens[index];x=64+col*44;y=286+row*48-int(self.score_scroll)
                    if y+26<clip[1] or y-24>=clip[3]:continue
                    if kind=='note':c.note(value,x,y,22,C['ink'],rhythm=True,clip=clip)
                    elif kind=='dash':c.clipped_rect((x-7,y,x+8,y+2),C['ink'],clip)
                    else:c.clipped_rect((x,y-12,x+1,y+15),C['muted'],clip)
            total_rows=max(3,(len(self._tokens)+15)//16)
            if total_rows>3:
                height=max(16,int(138*3/total_rows));top=268+int((138-height)*self.score_scroll/max(1,self._max_score_scroll()))
                c.rounded((762,268,765,406),1,C['soft']);c.rounded((762,top,765,top+height),1,C['muted'])
        labels={'record':'pause_record' if self.recording else 'resume_record','latest':'latest','save':'save',
                'clear_notes':'confirm_clear' if now<self._clear_until else 'clear_notes'}
        for key,b in NOTATION_BUTTONS.items():
            primary=key=='record' and self.recording
            active=(key=='latest' and self.follow_latest) or (key=='clear_notes' and now<self._clear_until)
            c.rounded(b,14,C['selected'] if primary else C['accent_light'] if active else C['white'],None if primary else C['line'])
            c.text(labels[key],(b[0]+b[2])//2,446,C['background'] if primary else C['accent'] if active else C['ink'],True)


    def render(self, now):
        c=self.canvas
        c.image[:]=C['background']
        if self.closed:
            c.text('home_title',400,202,C['ink'],True)
            c.text('exited',400,252,C['muted'],True)
            return c.image
        if self.page=='home':self._home()
        elif self.page=='metronome':self._metronome_page(now)
        elif self.page=='spectrum':self._spectrum_page(now)
        elif self.page=='notation':self._notation_page(now)
        else:self._instrument_page(now)
        self._header()
        if now<self._notice_until:
            c.rounded((240,208,560,252),14,C['selected'])
            c.text(self._notice,400,230,C['background'],True)
        return c.image

    def _instrument_name(self):
        return {'piano':'instrument_piano','guitar':'instrument_guitar','violin':'instrument_violin'}.get(
            getattr(self,'instrument_label',None),'instrument_wait')

